function ColumnChooser({
  caption = "{{caption}}",
  accent = "{{accent}}",
  showEmail = {{showEmail}},
  showRole = {{showRole}},
  showJoined = {{showJoined}},
}) {
  const people = [
    { name: "A. Whitfield", email: "a.whitfield@example.com", role: "Engineer", joined: "2021", status: "Active" },
    { name: "R. Okafor", email: "r.okafor@example.com", role: "Designer", joined: "2019", status: "Active" },
    { name: "M. Iqbal", email: "m.iqbal@example.com", role: "Manager", joined: "2017", status: "Away" },
    { name: "S. Novak", email: "s.novak@example.com", role: "Engineer", joined: "2022", status: "Active" },
  ];
  const cell = { padding: "10px 14px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap" };
  const opts = [
    ["Name", true, true],
    ["Email", showEmail, false],
    ["Role", showRole, false],
    ["Joined", showJoined, false],
    ["Status", true, true],
  ];
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <fieldset style={{ display: "flex", flexWrap: "wrap", gap: 10, border: 0, borderBottom: "1px solid #24143020", padding: "10px 14px", margin: 0 }}>
        <legend style={{ fontWeight: 600, paddingBottom: 6, width: "100%" }}>Columns</legend>
        {opts.map(([label, checked]) => (
          <label key={label} style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 13 }}>
            <input type="checkbox" checked={checked} disabled style={{ accentColor: accent }} readOnly /><span>{label}</span>
          </label>
        ))}
      </fieldset>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>{caption}</caption>
          <thead>
            <tr style={{ background: accent, color: "#FAF7F2" }}>
              <th scope="col" style={cell}>Name</th>
              {showEmail && <th scope="col" style={cell}>Email</th>}
              {showRole && <th scope="col" style={cell}>Role</th>}
              {showJoined && <th scope="col" style={cell}>Joined</th>}
              <th scope="col" style={cell}>Status</th>
            </tr>
          </thead>
          <tbody>
            {people.map((p) => (
              <tr key={p.name}>
                <td style={cell}>{p.name}</td>
                {showEmail && <td style={cell}>{p.email}</td>}
                {showRole && <td style={cell}>{p.role}</td>}
                {showJoined && <td style={cell}>{p.joined}</td>}
                <td style={cell}>{p.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
